/**
 * contracts.ts
 *
 * Maps chainId → Vantage contract addresses.
 * Values are sourced from addresses.ts (auto-generated by `pnpm sync`).
 *
 * Usage:
 *   import { getVantageContractAddress } from "vantage/contracts";
 *   const addr = getVantageContractAddress(chainId, "Vault");
 */

import { ARBITRUM, ARBITRUM_SEPOLIA } from "config/chains";

import {
  ARBITRUM_ASSET_REGISTRY,
  ARBITRUM_CHAINLINK_ADAPTER,
  ARBITRUM_COMPLIANCE_REGISTRY,
  ARBITRUM_LP_MANAGER,
  ARBITRUM_LP_TOKEN,
  ARBITRUM_MANUAL_ADAPTER,
  ARBITRUM_MULTI_ORACLE_MIDDLEWARE,
  ARBITRUM_ORDER_BOOK,
  ARBITRUM_POSITION_ROUTER,
  ARBITRUM_ROUTER,
  ARBITRUM_SEPOLIA_ASSET_REGISTRY,
  ARBITRUM_SEPOLIA_CHAINLINK_ADAPTER,
  ARBITRUM_SEPOLIA_COMPLIANCE_REGISTRY,
  ARBITRUM_SEPOLIA_LP_MANAGER,
  ARBITRUM_SEPOLIA_LP_TOKEN,
  ARBITRUM_SEPOLIA_MANUAL_ADAPTER,
  ARBITRUM_SEPOLIA_MULTI_ORACLE_MIDDLEWARE,
  ARBITRUM_SEPOLIA_ORDER_BOOK,
  ARBITRUM_SEPOLIA_POSITION_ROUTER,
  ARBITRUM_SEPOLIA_ROUTER,
  ARBITRUM_SEPOLIA_SHARED_PAYOUT_HUB,
  ARBITRUM_SEPOLIA_UNIVERSAL_PRICE_LOGIC,
  ARBITRUM_SEPOLIA_VAULT,
  ARBITRUM_SEPOLIA_VAULT_FACTORY,
  ARBITRUM_SEPOLIA_VAULT_READER,
  ARBITRUM_SEPOLIA_YIELD_ACCUMULATOR,
  ARBITRUM_SEPOLIA_YIELD_AWARE_PRICE_FEED,
  ARBITRUM_SHARED_PAYOUT_HUB,
  ARBITRUM_UNIVERSAL_PRICE_LOGIC,
  ARBITRUM_VAULT,
  ARBITRUM_VAULT_FACTORY,
  ARBITRUM_VAULT_READER,
  ARBITRUM_YIELD_ACCUMULATOR,
  ARBITRUM_YIELD_AWARE_PRICE_FEED,
} from "./addresses";

// ---------------------------------------------------------------------------
// Contract name registry
// ---------------------------------------------------------------------------

export type VantageContractName =
  | "AssetRegistry"
  | "ChainlinkAdapter"
  | "ComplianceRegistry"
  | "LPManager"
  | "LPToken"
  | "ManualAdapter"
  | "MultiOracleMiddleware"
  | "OrderBook"
  | "PositionRouter"
  | "Router"
  | "SharedPayoutHub"
  | "UniversalPriceLogic"
  | "Vault"
  | "VaultFactory"
  | "VaultReader"
  | "YieldAccumulator"
  | "YieldAwarePriceFeed";

type VantageAddressMap = Record<VantageContractName, string>;

const VANTAGE_CONTRACTS: Record<number, VantageAddressMap> = {
  [ARBITRUM]: {
    AssetRegistry: ARBITRUM_ASSET_REGISTRY,
    ChainlinkAdapter: ARBITRUM_CHAINLINK_ADAPTER,
    ComplianceRegistry: ARBITRUM_COMPLIANCE_REGISTRY,
    LPManager: ARBITRUM_LP_MANAGER,
    LPToken: ARBITRUM_LP_TOKEN,
    ManualAdapter: ARBITRUM_MANUAL_ADAPTER,
    MultiOracleMiddleware: ARBITRUM_MULTI_ORACLE_MIDDLEWARE,
    OrderBook: ARBITRUM_ORDER_BOOK,
    PositionRouter: ARBITRUM_POSITION_ROUTER,
    Router: ARBITRUM_ROUTER,
    SharedPayoutHub: ARBITRUM_SHARED_PAYOUT_HUB,
    UniversalPriceLogic: ARBITRUM_UNIVERSAL_PRICE_LOGIC,
    Vault: ARBITRUM_VAULT,
    VaultFactory: ARBITRUM_VAULT_FACTORY,
    VaultReader: ARBITRUM_VAULT_READER,
    YieldAccumulator: ARBITRUM_YIELD_ACCUMULATOR,
    YieldAwarePriceFeed: ARBITRUM_YIELD_AWARE_PRICE_FEED,
  },
  [ARBITRUM_SEPOLIA]: {
    AssetRegistry: ARBITRUM_SEPOLIA_ASSET_REGISTRY,
    ChainlinkAdapter: ARBITRUM_SEPOLIA_CHAINLINK_ADAPTER,
    ComplianceRegistry: ARBITRUM_SEPOLIA_COMPLIANCE_REGISTRY,
    LPManager: ARBITRUM_SEPOLIA_LP_MANAGER,
    LPToken: ARBITRUM_SEPOLIA_LP_TOKEN,
    ManualAdapter: ARBITRUM_SEPOLIA_MANUAL_ADAPTER,
    MultiOracleMiddleware: ARBITRUM_SEPOLIA_MULTI_ORACLE_MIDDLEWARE,
    OrderBook: ARBITRUM_SEPOLIA_ORDER_BOOK,
    PositionRouter: ARBITRUM_SEPOLIA_POSITION_ROUTER,
    Router: ARBITRUM_SEPOLIA_ROUTER,
    SharedPayoutHub: ARBITRUM_SEPOLIA_SHARED_PAYOUT_HUB,
    UniversalPriceLogic: ARBITRUM_SEPOLIA_UNIVERSAL_PRICE_LOGIC,
    Vault: ARBITRUM_SEPOLIA_VAULT,
    VaultFactory: ARBITRUM_SEPOLIA_VAULT_FACTORY,
    VaultReader: ARBITRUM_SEPOLIA_VAULT_READER,
    YieldAccumulator: ARBITRUM_SEPOLIA_YIELD_ACCUMULATOR,
    YieldAwarePriceFeed: ARBITRUM_SEPOLIA_YIELD_AWARE_PRICE_FEED,
  },
};

// ---------------------------------------------------------------------------
// Lookup helper
// ---------------------------------------------------------------------------

export function getVantageContractAddress(chainId: number, name: VantageContractName): string {
  const map = VANTAGE_CONTRACTS[chainId];
  if (!map) {
    throw new Error(`Vantage contracts not configured for chainId: ${chainId}`);
  }
  return map[name];
}
